package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.json.*;
import org.junit.*;

/** Real selected files and original query cursors, not a byte-pattern permission/AST claim. */
public final class ProjectHexSearchTest {
    private Path root;private static final String CHECKOUT="11111111-1111-1111-1111-111111111111";
    @Before public void create()throws Exception{root=Files.createTempDirectory("pw-hex-search-");}
    @After public void close()throws Exception{try(var paths=Files.walk(root)){for(Path path:paths.sorted(Comparator.reverseOrder()).collect(java.util.stream.Collectors.toList()))Files.deleteIfExists(path);}}
    private JSONObject input(String query)throws Exception{return new JSONObject().put("mode","hex").put("path","data.bin").put("query",query);}
    private JSONObject search(JSONObject input)throws Exception{return ProjectFileQueries.search(root.toFile(),CHECKOUT,input,()->{});}
    @Test public void realBinaryOverlapsReturnByteOffsetsAndResumeUnderTheSamePathPatternAndSha()throws Exception{Files.write(root.resolve("data.bin"),new byte[]{0,0,0,0,0});JSONObject first=search(input("0000").put("limit",2));assertEquals("bounded_streaming_kmp_v1",first.getString("patternEngine"));assertEquals(0,first.getJSONArray("matches").getJSONObject(0).getLong("byteOffset"));assertEquals(1,first.getJSONArray("matches").getJSONObject(1).getLong("byteOffset"));assertEquals(2,first.getJSONObject("nextCursor").getLong("byteOffset"));assertTrue(first.getBoolean("hasMore"));JSONObject last=search(input("0000").put("limit",2).put("cursor",first.getJSONObject("nextCursor")));assertEquals(2,last.getJSONArray("matches").getJSONObject(0).getLong("byteOffset"));assertEquals(3,last.getJSONArray("matches").getJSONObject(1).getLong("byteOffset"));assertEquals(first.getString("sha256"),last.getString("sha256"));assertFalse(last.getBoolean("hasMore"));assertTrue(last.isNull("nextCursor"));assertEquals(2,last.getJSONArray("matches").getJSONObject(0).getInt("byteLength"));assertFalse(last.has("content"));}
    @Test public void foreignPatternPathFileVersionOrMalformedCursorNeverBecomesAFreshUnpinnedSearch()throws Exception{Files.write(root.resolve("data.bin"),new byte[]{0,0,0,0,0});Files.write(root.resolve("other.bin"),new byte[]{0,0,0,0,0});JSONObject cursor=search(input("00").put("limit",1)).getJSONObject("nextCursor");assertThrows(SecurityException.class,()->search(input("01").put("cursor",cursor)));assertThrows(SecurityException.class,()->search(input("00").put("path","other.bin").put("cursor",cursor)));for(Object position:new Object[]{-1,6,1.5,"1",true})assertThrows(Exception.class,()->search(input("00").put("cursor",new JSONObject(cursor.toString()).put("byteOffset",position))));assertThrows(SecurityException.class,()->search(input("00").put("cursor",new JSONObject(cursor.toString()).put("unknown",true))));Files.write(root.resolve("data.bin"),new byte[]{0,0,0,0,1});assertThrows(SecurityException.class,()->search(input("00").put("cursor",cursor)));}
    @Test public void scanBudgetReturnsAProgressCursorEvenWithNoHitsAndKeepsACrossBoundaryMatch()throws Exception{byte[] bytes=new byte[ProjectHexPattern.MAX_SCAN_BYTES+8];int at=ProjectHexPattern.MAX_SCAN_BYTES-2;bytes[at]=1;bytes[at+1]=2;bytes[at+2]=3;bytes[at+3]=4;Files.write(root.resolve("data.bin"),bytes);JSONObject first=search(input("01020304"));assertEquals(0,first.getJSONArray("matches").length());assertTrue(first.getBoolean("hasMore"));assertTrue(first.getBoolean("scanBudgetExhausted"));assertEquals(at,first.getJSONObject("nextCursor").getLong("byteOffset"));JSONObject next=search(input("01020304").put("cursor",first.getJSONObject("nextCursor")));assertEquals(at,next.getJSONArray("matches").getJSONObject(0).getLong("byteOffset"));assertFalse(next.getBoolean("hasMore"));}
    @Test public void hexRequiresExactEligibleFileAndExplicitHiddenChoiceAndRefusesIrrelevantTextScopeOptions()throws Exception{Files.write(root.resolve("data.bin"),new byte[]{0,1});assertThrows(Exception.class,()->search(new JSONObject().put("mode","hex").put("query","00")));assertThrows(Exception.class,()->search(input("00").put("path","../data.bin")));Files.createDirectories(root.resolve("folder"));assertThrows(Exception.class,()->search(input("00").put("path","folder")));Files.createDirectories(root.resolve("node_modules"));Files.write(root.resolve("node_modules/secret.bin"),new byte[]{0,1});assertThrows(SecurityException.class,()->search(input("00").put("path","node_modules/secret.bin")));Files.createDirectories(root.resolve(".hidden"));Files.write(root.resolve(".hidden/data.bin"),new byte[]{0,1});assertThrows(SecurityException.class,()->search(input("00").put("path",".hidden/data.bin")));assertEquals(1,search(input("00").put("path",".hidden/data.bin").put("hidden",true)).getJSONArray("matches").length());for(String option:new String[]{"include","syntax","caseSensitive","contextBefore","contextAfter"})assertThrows(IllegalArgumentException.class,()->search(input("00").put(option,option.equals("caseSensitive")?false:0)));for(String pattern:new String[]{"","0","0x00","00 00","gg"})assertThrows(IllegalArgumentException.class,()->search(input(pattern)));}
    @Test public void longPathOutputBudgetIsExplicitAndNoHitIsSkippedWhenRemainingMatchesAreReRead()throws Exception{String path="a".repeat(150)+"/"+"b".repeat(60)+".bin";Files.createDirectories(root.resolve(path).getParent());Files.write(root.resolve(path),new byte[100]);List<Long> found=new ArrayList<>();JSONObject request=input("00").put("path",path).put("limit",40),page=search(request);assertTrue(page.getBoolean("resultBudgetExhausted"));int pages=0;while(true){assertTrue(page.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=12000);JSONArray matches=page.getJSONArray("matches");for(int i=0;i<matches.length();i++)found.add(matches.getJSONObject(i).getLong("byteOffset"));if(!page.getBoolean("hasMore"))break;assertTrue(matches.length()>0);request.put("cursor",page.getJSONObject("nextCursor"));page=search(request);assertTrue(++pages<20);}assertEquals(100,found.size());for(int i=0;i<100;i++)assertEquals((long)i,found.get(i).longValue());}
    @Test public void originalCancellationAndChangedByteSourceCannotYieldAnEmptySuccessPage()throws Exception{Files.write(root.resolve("data.bin"),new byte[]{0,1,2,3});assertThrows(InterruptedException.class,()->ProjectFileQueries.search(root.toFile(),CHECKOUT,input("01"),()->{throw new InterruptedException("original stop");}));AtomicInteger checks=new AtomicInteger();assertThrows(SecurityException.class,()->ProjectFileQueries.search(root.toFile(),CHECKOUT,input("01"),()->{if(checks.incrementAndGet()==3)Files.write(root.resolve("data.bin"),new byte[]{0,4,5,6});}));}
}
